// Function f implemented as a one-hot SOP (Sum of Products) with
// combinational logic to go to the next SOP stage.
module TopModule(
    input  [3:0] x,
    output reg  f
);
    reg [1:0] sop_stage1;
    reg sop_stage2;
    always @* begin
        case (x)
            4'b0000: sop_stage1 = 2'b00;
            4'b0001: sop_stage1 = 2'b01;
            4'b0010: sop_stage1 = 2'b11;
            4'b0011: sop_stage1 = 2'b10;
            4'b0100: sop_stage1 = 2'b00;
            4'b0101: sop_stage1 = 2'b00;
            4'b0110: sop_stage1 = 2'b00;
            4'b0111: sop_stage1 = 2'b00;
            4'b1000: sop_stage1 = 2'b10;
            4'b1001: sop_stage1 = 2'b10;
            4'b1010: sop_stage1 = 2'b10;
            4'b1011: sop_stage1 = 2'b01;
            4'b1100: sop_stage1 = 2'b01;
            4'b1101: sop_stage1 = 2'b01;
            4'b1110: sop_stage1 = 2'b01;
            4'b1111: sop_stage1 = 2'b00;
        endcase
    end
    always @* begin
        case (sop_stage1)
            2'b00: sop_stage2 = 1'b1;
            2'b01: sop_stage2 = 1'b0;
            2'b10: sop_stage2 = 1'b1;
            2'b11: sop_stage2 = 1'b0;
        endcase
    end
    always @(posedge sop_stage2) f <= ~f;
endmodule

